∀ {k r s : ℕ}
  (M : CommodityClassification.FixedAnswer.Mat r s),
  0 < k → (∀ (X : CommodityClassification.FixedAnswer.Mat s k), M * X = 0) → M = 0

∀ {n r s : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n 0 r) (U : CommodityClassification.FixedAnswer.Mat n s)
  (Ω : Set (CommodityClassification.FixedAnswer.Mat s 0)), (a.withDirections U).ConstantOn Ω

∀ {k : ℕ}
  {A : ℝ → CommodityClassification.FixedAnswer.Mat k k} {A' : CommodityClassification.FixedAnswer.Mat k k} {t : ℝ},
  HasDerivAt A A' t → IsUnit (Matrix.det (A t)) → HasDerivAt (fun z => (A z)⁻¹) (-((A t)⁻¹ * A' * (A t)⁻¹)) t

∀ {n k r : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n k r) (C B : CommodityClassification.FixedAnswer.Mat n k),
  (a.atMatrix C).K B = a.K B

∀ {n k r : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n k r) (C B : CommodityClassification.FixedAnswer.Mat n k),
  (a.atMatrix C).m B = a.m B

∀ {n k r : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n k r) (C B : CommodityClassification.FixedAnswer.Mat n k),
  (a.atMatrix C).F B = a.F B

∀ {n g h r s : ℕ}
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0) (q : CommodityClassification.InputCoordinates.Vec n)
  (H : CommodityClassification.InputCoordinates.HiddenBasis (P.Q q) r)
  (H0 : CommodityClassification.InputCoordinates.HiddenBasis (P0.Q q) s), ∃ J, H.N = H0.N * J

∀ {n k r : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n k r),
  Matrix.PosDef a.K₀ → a.A_N ≠ 0 → a.K₀⁻¹ * Matrix.transpose a.A_N ≠ 0

∀ {k r s : ℕ}
  (M : CommodityClassification.FixedAnswer.Mat r s) (E : CommodityClassification.FixedAnswer.Mat k r) (a : Fin s)
  (b : Fin k) (i j : Fin r), (M * Matrix.single a b 1 * E) i j = M i a * E b j

∀ {s : ℕ}
  (B : CommodityClassification.FixedAnswer.Mat s s),
  Matrix.transpose B = B → (∀ (x : CommodityClassification.FixedAnswer.Vec s), x ⬝ᵥ Matrix.mulVec B x = 0) → B = 0

∀ {n : ℕ}
  (S : Submodule ℝ (CommodityClassification.InputCoordinates.Vec n)),
  ∃ m, Nonempty (CommodityClassification.InputCoordinates.VectorBasis S m)

∀ {n k m : ℕ}
  (S : Submodule ℝ (CommodityClassification.InputCoordinates.Vec n))
  (B : CommodityClassification.InputCoordinates.VectorBasis S m), Function.Injective fun X => B.B * X

∀ {n k m : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p : CommodityClassification.InputCoordinates.Vec n)
  (C0 : CommodityClassification.InputCoordinates.Mat n k) (B : CommodityClassification.InputCoordinates.Mat n m),
  IsOpen {X | C0 + B * X ∈ e.PositiveDomain p}

∀ {n k m : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p : CommodityClassification.InputCoordinates.Vec n)
  (C0 : CommodityClassification.InputCoordinates.Mat n k) (B : CommodityClassification.InputCoordinates.Mat n m),
  C0 ∈ e.PositiveDomain p → 0 ∈ {X | C0 + B * X ∈ e.PositiveDomain p}

∀ {n g h k : ℕ}
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) →
    (∀ (i : Fin n), 0 < q i) →
      ∀ (C : CommodityClassification.InputCoordinates.Mat n k), P.mean p q (P0.mean p q C) = P0.mean p q C

∀ {n g r : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n)
  (H : CommodityClassification.InputCoordinates.HiddenBasis (P.Q q) r), P.meanProjection p q * H.N = 0

∀ {n g k : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n)
  (C : CommodityClassification.InputCoordinates.Mat n k), P.mean p q C = P.liftReport p q * P.report q C

∀ {n g : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) → (∀ (i : Fin n), 0 < q i) → P.report q (P.liftReport p q) = 1

∀ {n g k : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n)
  (C : CommodityClassification.InputCoordinates.Mat n k), P.meanProjection p q * C = P.mean p q C

∀ {n g : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) → (∀ (i : Fin n), 0 < q i) → P.meanProjection p q * P.liftReport p q = P.liftReport p q

∀ {n g : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q x : CommodityClassification.InputCoordinates.Vec n),
  (Matrix.transpose (P.Q q)).mulVec x = 0 → Matrix.mulVec (P.meanProjection p q) x = 0

∀ {n g h : ℕ}
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) →
    (∀ (i : Fin n), 0 < q i) → Matrix.transpose (P0.Q q) * P.meanProjection p q = Matrix.transpose (P0.Q q)

∀ {n g h : ℕ}
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) →
    (∀ (i : Fin n), 0 < q i) →
      ∀ (x : CommodityClassification.InputCoordinates.Vec n),
        (Matrix.transpose (P0.Q q)).mulVec x = 0 →
          (Matrix.transpose (P0.Q q)).mulVec (Matrix.mulVec (P.meanProjection p q) x) = 0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (σ : ℝ),
  σ ≠ 1 → ∀ (j : Fin f), HasFDerivAt (d.cesGradient σ j) (d.hessianRow σ j) d.w0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (σ : ℝ),
  σ ≠ 1 → ∀ (j : Fin f), HasFDerivAt (CommodityClassification.CESCost.pricePartial (d.ces σ) j) (d.hessianRow σ j) d.w0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (w : CommodityClassification.CESCost.Vec f),
  HasDerivAt (d.parameterSum w) (d.logSum w) 0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (w : CommodityClassification.CESCost.Vec f),
  HasDerivAt (fun t => Real.log (d.parameterSum w t)) (d.logSum w) 0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (w : CommodityClassification.CESCost.Vec f),
  Filter.Tendsto (fun t => Real.log (d.parameterSum w t) / t) (nhdsWithin 0 {0}ᶜ) (nhds (d.logSum w))

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) {w : CommodityClassification.CESCost.Vec f},
  w ∈ CommodityClassification.CESCost.PositivePrices f → ContinuousAt (fun σ => d.cost σ w) 1

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (i : Fin n) (w : CommodityClassification.Equilibrium.Vec (k + 1))
  (y : ℝ), (E.costData i).optimalInput E.sigma w y = y • E.currentInputs w i

∀ {n k h : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k h) {i j : Fin n},
  F.SamePolicyAttributes i j → F.SamePolicyAttributes j i

∀ {n k h : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k h) {i j l : Fin n},
  F.SamePolicyAttributes i j → F.SamePolicyAttributes j l → F.SamePolicyAttributes i l

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f),
  HasFDerivAt d.cobb (CommodityClassification.CESCost.weightedLinear d.a) d.w0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (j : Fin f),
  HasFDerivAt (CommodityClassification.CESCost.pricePartial d.cobb j) (d.hessianRow 1 j) d.w0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (s0 : ℝ),
  E.taxTransfer 0 = 0 ∧ E.householdIncome (E.endowment s0) 0 = E.frame.w ⬝ᵥ E.endowment s0

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : F.Candidate),
  (Matrix.transpose (F.model C).A).mulVec F.q = (Matrix.transpose (F.frame.reconstruct F.p F.reference)).mulVec F.q

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : F.Candidate) (s0 : ℝ),
  (F.model C).endowment s0 = F.commonEndowment s0

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) {s0 : ℝ},
  0 < s0 → ∀ (j : Fin (k + 1)), 0 < F.commonEndowment s0 j

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (c : ℝ),
  HasFDerivAt (F.commonUtility c) (CommodityClassification.CESCost.weightedLinear F.p) F.q

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (c : ℝ),
  StrictConcaveOn ℝ Set.univ (F.commonUtility c)

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : F.Candidate) (c : ℝ),
  (F.model C).UtilityCompatible (F.commonUtility c)

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : F.Candidate),
  HasFDerivAt (F.model C).demand (-CommodityClassification.Equilibrium.matCLM F.D) F.p

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) {s0 : ℝ},
  0 < s0 → ∀ (c : ℝ) (C : F.Candidate), (F.model C).BenchmarkEquilibrium (F.commonUtility c) (F.commonEndowment s0) s0

∀ {n : ℕ}
  (p q : CommodityClassification.Equilibrium.Vec n) (D : CommodityClassification.Equilibrium.Mat n n) (c : ℝ),
  CommodityClassification.Equilibrium.benchmarkUtility p q D c q = c

∀ {n : ℕ}
  (p q : CommodityClassification.Equilibrium.Vec n) (D : CommodityClassification.Equilibrium.Mat n n),
  Continuous (CommodityClassification.Equilibrium.benchmarkGradient p q D)

∀ {n : ℕ}
  (p q : CommodityClassification.Equilibrium.Vec n) (D : CommodityClassification.Equilibrium.Mat n n),
  Matrix.PosDef D → ∀ (c : ℝ), StrictConcaveOn ℝ Set.univ (CommodityClassification.Equilibrium.benchmarkUtility p q D c)

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (v : CommodityClassification.InputCoordinates.Vec f),
  e.costDerivative v = Matrix.mulVec e.A v

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) {w : CommodityClassification.InputCoordinates.Vec f},
  (∀ (j : Fin f), 0 < w j) → 0 < e.compositeCost w

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) {w : CommodityClassification.InputCoordinates.Vec f},
  (∀ (j : Fin f), 0 < w j) →
    IsLeast {v | ∃ x, (∀ (i : Fin n), 0 ≤ x i) ∧ 1 ≤ e.nest.quantityOnNonnegative x ∧ v = e.costs w ⬝ᵥ x}
      (e.compositeCost w)

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) {w : CommodityClassification.InputCoordinates.Vec f},
  (∀ (j : Fin f), 0 < w j) → ∀ (i : Fin n), 0 < e.compositeMix w i

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) {w : CommodityClassification.InputCoordinates.Vec f},
  (∀ (j : Fin f), 0 < w j) → e.nest.quantityOnNonnegative (e.compositeMix w) = 1

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) {w : CommodityClassification.InputCoordinates.Vec f},
  (∀ (j : Fin f), 0 < w j) → ContDiffAt ℝ ⊤ e.compositeCost w

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f),
  HasFDerivAt e.compositeCost (CommodityClassification.CESCost.weightedLinear e.meanInputs) e.w0

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (j : Fin f),
  CommodityClassification.CESCost.pricePartial e.compositeCost j e.w0 = e.meanInputs j

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) {w : CommodityClassification.InputCoordinates.Vec f},
  (∀ (j : Fin f), 0 < w j) → HasFDerivAt e.costs (e.currentCostDerivative w) w

∀ {n g : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) → (∀ (i : Fin n), 0 < q i) → P.inverseSales p q * Matrix.diagonal (P.sales p q) = 1

∀ {n g : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) → (∀ (i : Fin n), 0 < q i) → Matrix.diagonal (P.sales p q) * P.inverseSales p q = 1

∀ {n k h g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k h)
  (P : CommodityClassification.InputCoordinates.Partition n g), Matrix.PosDef (P.groupDemand F.p F.D)

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (j : Fin f),
  HasFDerivAt (CommodityClassification.CESCost.pricePartial e.compositeCost j) (e.compositeHessianRow j) e.w0

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (j : Fin f) (v : CommodityClassification.InputCoordinates.Vec f),
  (e.compositeHessianRow j) v = Matrix.mulVec e.compositeHessian v j

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (j : Fin f),
  e.meanCostData.share j = e.w0 j * CommodityClassification.Supply.totalInputs e.nest.q e.A j / e.nest.sales

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (j : Fin f),
  e.meanCostData.share j = ∑ i, e.nest.share i * (e.costData i).share j

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (s : ℝ) (w : CommodityClassification.InputCoordinates.Vec f),
  e.meanCostData.powerSum s w = ∑ i, e.nest.share i * (e.costData i).powerSum s w

∀ {n f : ℕ}
  (e : CommodityClassification.Composite.Data n f) (w : CommodityClassification.InputCoordinates.Vec f),
  e.meanCostData.logSum w = ∑ i, e.nest.share i * (e.costData i).logSum w

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (σ : ℝ),
  HasFDerivAt (d.cost σ) (CommodityClassification.CESCost.weightedLinear d.a) d.w0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (σ : ℝ) (j : Fin f),
  HasFDerivAt (CommodityClassification.CESCost.pricePartial (d.cost σ) j) (d.hessianRow σ j) d.w0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (σ : ℝ) (v : CommodityClassification.CESCost.Vec f),
  HasFDerivAt (fun w => (fderiv ℝ (d.cost σ) w) v) (∑ j, v j • d.hessianRow σ j) d.w0

∀ {f : ℕ}
  (d : CommodityClassification.CESCost.Data f) (σ : ℝ) (u v : CommodityClassification.CESCost.Vec f),
  (fderiv ℝ (fun w => (fderiv ℝ (d.cost σ) w) v) d.w0) u = (fderiv ℝ (fun w => (fderiv ℝ (d.cost σ) w) u) d.w0) v

∀ {n : ℕ}
  (B : CommodityClassification.Regularity.Mat n n) (hB : Matrix.IsHermitian B) (hn : 0 < n),
  IsLeast (spectrum ℝ B) (CommodityClassification.Regularity.minEigen B hB hn)

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (D : CommodityClassification.Equilibrium.Mat n n)
  (hD : Matrix.PosDef D), (F.withDemand D hD).Candidate = F.Candidate

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : CommodityClassification.Equilibrium.Mat n k),
  F.coefficient C = F.b ⬝ᵥ Matrix.mulVec F.D F.b - F.demandGain F.D C

∀ {n k g h : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k h)
  (P : CommodityClassification.InputCoordinates.Partition n g), F.ReportMomentsPreserved P → F.ReportIdentified P

∀ {n k g h : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k h)
  (P : CommodityClassification.InputCoordinates.Partition n g), F.ParentIdentified → F.ReportIdentified P

∀ {n g h : ℕ}
  (F0 : CommodityClassification.Equilibrium.BenchmarkFamily n 0 h)
  (P : CommodityClassification.InputCoordinates.Partition n g) (C0 : F0.Candidate), F0.IdentifiedAt P C0

∀ {n k g h : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p q : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < p i) →
    (∀ (i : Fin n), 0 < q i) →
      ∀ {P : CommodityClassification.InputCoordinates.Partition n g}
        {P0 : CommodityClassification.InputCoordinates.Partition n h}
        (R : CommodityClassification.InputCoordinates.Refinement P P0)
        (J0 : CommodityClassification.InputCoordinates.Mat h k),
        ∀ C ∈ e.Candidates p q P0 J0, P.mean p q C ∈ e.Candidates p q P0 J0 ∧ P.report q (P.mean p q C) = P.report q C

∀ {n k g h r : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p q : CommodityClassification.InputCoordinates.Vec n)
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0)
  (J0 : CommodityClassification.InputCoordinates.Mat h k),
  ∀ C0 ∈ e.Candidates p q P0 J0,
    ∀ (H : CommodityClassification.InputCoordinates.HiddenBasis (P.Q q) r),
      e.FixedFiber p q P0 J0 P C0 = (fun Z => C0 + H.N * Z) '' e.FiberDomain p H C0

∀ {n k g h r : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p q : CommodityClassification.InputCoordinates.Vec n)
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0)
  (J0 : CommodityClassification.InputCoordinates.Mat h k),
  ∀ C0 ∈ e.Candidates p q P0 J0,
    ∀ (H : CommodityClassification.InputCoordinates.HiddenBasis (P.Q q) r)
      (C : CommodityClassification.InputCoordinates.Mat n k),
      C ∈ e.FixedFiber p q P0 J0 P C0 ↔ ∃! Z, Z ∈ e.FiberDomain p H C0 ∧ C = C0 + H.N * Z

∀ {n k g h r : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p q : CommodityClassification.InputCoordinates.Vec n)
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0)
  (J0 : CommodityClassification.InputCoordinates.Mat h k),
  ∀ C0 ∈ e.Candidates p q P0 J0,
    ∀ (H : CommodityClassification.InputCoordinates.HiddenBasis (P.Q q) r),
      ∀ᶠ (Z : CommodityClassification.InputCoordinates.Mat r k) in nhds 0, C0 + H.N * Z ∈ e.FixedFiber p q P0 J0 P C0

∀ {n k g h : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p q : CommodityClassification.InputCoordinates.Vec n)
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0)
  (J0 : CommodityClassification.InputCoordinates.Mat h k),
  ∀ C0 ∈ e.Candidates p q P0 J0,
    ∀ (H : CommodityClassification.InputCoordinates.HiddenBasis (P.Q q) 0), e.FixedFiber p q P0 J0 P C0 = {C0}

∀ {n k g h : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (p q : CommodityClassification.InputCoordinates.Vec n)
  {P : CommodityClassification.InputCoordinates.Partition n g}
  {P0 : CommodityClassification.InputCoordinates.Partition n h}
  (R : CommodityClassification.InputCoordinates.Refinement P P0)
  (J0 : CommodityClassification.InputCoordinates.Mat h k),
  ∀ C0 ∈ e.Candidates p q P0 J0,
    ∃ r H,
      IsOpen (e.FiberDomain p H C0) ∧
        0 ∈ e.FiberDomain p H C0 ∧ e.FixedFiber p q P0 J0 P C0 = (fun Z => C0 + H.N * Z) '' e.FiberDomain p H C0

∀ {n : ℕ}
  (p q : CommodityClassification.Equilibrium.Vec n) (D : CommodityClassification.Equilibrium.Mat n n),
  HasFDerivAt (CommodityClassification.Equilibrium.affineDemand p q D) (-CommodityClassification.Equilibrium.matCLM D) p

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (i : Fin n) (j l : Fin (k + 1)),
  E.hessian i j l = E.sigma * (E.A i j * E.A i l / E.p i - if j = l then E.A i j / E.frame.w j else 0)

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (y : CommodityClassification.Equilibrium.PolicyPrice k),
  E.priceChange y = Matrix.mulVec E.C y.2 + y.1 • E.b

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (y : CommodityClassification.Equilibrium.PolicyPrice k),
  E.quantityChange y = -Matrix.mulVec E.D (Matrix.mulVec E.C y.2 + y.1 • E.b)

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (ys : CommodityClassification.Equilibrium.PolicyPrice k × ℝ),
  E.excessChange ys = E.factorChange ys.1 + ys.2 • E.frame.a0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (u : CommodityClassification.Equilibrium.Vec k),
