  (e : CommodityClassification.InputCoordinates.Frame k) {z : CommodityClassification.Supply.Vec k},
  z ≠ 0 → ¬∃ t, Matrix.mulVec e.V z = t • e.w

∀ {k : ℕ}
  (e : CommodityClassification.InputCoordinates.Frame k) (d : CommodityClassification.CESCost.Data (k + 1)),
  d.w0 = e.w → (Matrix.transpose e.V * CommodityClassification.Supply.curvature d.a d.w0 d.p * e.V).PosDef

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g),
  0 < n → ∀ (C : F.Candidate), Matrix.PosDef (F.supplyT ↑C)

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : F.Candidate),
  F.supplyT ↑C = (F.model C).substitutionMatrix

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g),
  0 < n → ∀ (C : F.Candidate), Matrix.transpose (F.supplyResponse ↑C) = F.supplyResponse ↑C

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (s0 : ℝ) (u : ℝ → CommodityClassification.Equilibrium.Vec k)
  (s : ℝ → ℝ), E.PositiveLocalPath s0 u s → Filter.Tendsto (fun t => E.prices (t, u t)) (nhds 0) (nhds E.p)

∀ {n : ℕ}
  (P : MvPolynomial (CommodityClassification.Genericity.SymmetricEntry n) ℝ),
  Continuous fun D => (MvPolynomial.eval (CommodityClassification.Genericity.symmetricCoordinates D)) P

∀ {n : ℕ}
  (P : MvPolynomial (CommodityClassification.Genericity.SymmetricEntry n) ℝ),
  IsClosed {D | (MvPolynomial.eval (CommodityClassification.Genericity.symmetricCoordinates D)) P = 0}

∀ {n : ℕ}
  (b v : CommodityClassification.FixedAnswer.Vec n),
  b ≠ 0 → v ≠ 0 → (1 / 2) • (Matrix.vecMulVec b v + Matrix.vecMulVec v b) ≠ 0

∀ {n : ℕ}
  (b v : CommodityClassification.FixedAnswer.Vec n),
  b ≠ 0 → v ≠ 0 → CommodityClassification.Genericity.pairFunctional b v ≠ 0

∀ {n : ℕ}
  (b v : CommodityClassification.FixedAnswer.Vec n),
  b ≠ 0 → v ≠ 0 → (CommodityClassification.Genericity.pairFunctional b v).ker ≠ ⊤

∀ {n : ℕ}
  (b v : CommodityClassification.FixedAnswer.Vec n),
  b ≠ 0 → v ≠ 0 → Function.Surjective ⇑(CommodityClassification.Genericity.pairFunctional b v)

∀ {n : ℕ}
  (b v : CommodityClassification.FixedAnswer.Vec n),
  IsClosed ↑(CommodityClassification.Genericity.pairFunctional b v).ker

∀ {n : ℕ}
  (P : MvPolynomial (CommodityClassification.Genericity.SymmetricEntry n) ℝ),
  P ≠ 0 →
    ∀ (μ : MeasureTheory.Measure (CommodityClassification.Genericity.SymmetricDemand n)) [μ.IsAddHaarMeasure],
      IsOpen {D | (MvPolynomial.eval (CommodityClassification.Genericity.symmetricCoordinates D)) P ≠ 0} ∧
        Dense {D | (MvPolynomial.eval (CommodityClassification.Genericity.symmetricCoordinates D)) P ≠ 0}

∀ {n : ℕ}
  (D : CommodityClassification.Genericity.SymmetricDemand n),
  Matrix.PosDef ↑D ↔ ∀ (x : CommodityClassification.FixedAnswer.Vec n), ‖x‖ = 1 → 0 < x ⬝ᵥ Matrix.mulVec (↑D) x

∀ {k : ℕ}
  (M R : CommodityClassification.Regularity.Mat k k) (α : ℝ),
  Matrix.PosSemidef (M - α • R) → Matrix.PosDef R → 0 < α → Matrix.PosDef M

∀ {n : ℕ}
  (d : CommodityClassification.Precision.Data n) (l u : ℝ),
  0 < l → l ≤ u → d.sigmaConditionalWidth l u (d.sigmaCriticalInputs l u) = d.sigmaFloor l u

∀ {n : ℕ}
  (d : CommodityClassification.Precision.Data n) (l u : ℝ) (hl : 0 < l) (hlu : l ≤ u),
  let c := d.sigmaCriticalInputs l u;
  have hc := ⋯;
  ((d.withSigma u ⋯).family.model ((d.withSigma u ⋯).candidate c hc)).lossCoefficient / d.nu -
      ((d.withSigma l hl).family.model ((d.withSigma l hl).candidate c hc)).lossCoefficient / d.nu =
    d.sigmaFloor l u

∀ {n : ℕ}
  (d : CommodityClassification.Precision.Data n) (l : ℝ),
  0 < l → ∀ (c : CommodityClassification.InputCoordinates.Vec n), d.Admissible c → d.sigmaConditionalWidth l l c = 0

∀ {n : ℕ}
  (d : CommodityClassification.Precision.Data n) (l u : ℝ),
  0 < l → 0 < u → CommodityClassification.Precision.Envelope.bound l u d.totalElasticity d.lossScale = d.sigmaFloor l u

∀ {n : ℕ}
  (d : CommodityClassification.Precision.Data n) (s : ℝ) (c e : CommodityClassification.InputCoordinates.Vec n),
  d.momentReport c = d.momentReport e → d.sigmaWelfare s c = d.sigmaWelfare s e

∀ {n g : ℕ}
  (P : CommodityClassification.InputCoordinates.Partition n g) (q x : CommodityClassification.InputCoordinates.Vec n),
  (Matrix.transpose (P.Q q)).mulVec x = 0 → ∀ (a : Fin g), (∑ i, if P.group i = a then q i * x i else 0) = 0

∀ {n : ℕ}
  (q x : CommodityClassification.InputCoordinates.Vec n),
  (∀ (i : Fin n), 0 < q i) → ∑ i, (q i * x i) • (q i)⁻¹ • Pi.single i 1 = x

∀ {n : ℕ}
  (q d : CommodityClassification.InputCoordinates.Vec n) (i j : Fin n),
  CommodityClassification.InputCoordinates.weightedExchange q i j ⬝ᵥ d = d i / q i - d j / q j

∀ {n r : ℕ}
  (V : CommodityClassification.InputCoordinates.Mat n r) (z : CommodityClassification.InputCoordinates.Vec r),
  Matrix.mulVec V z = ∑ j, z j • fun i => V i j

∀ {n k : ℕ}
  {E : CommodityClassification.Equilibrium.Model n k} {s0 : ℝ} {utility : CommodityClassification.Equilibrium.Vec n → ℝ}
  {u : ℝ → CommodityClassification.Equilibrium.Vec k} {s : ℝ → ℝ},
  E.WelfareNeighborhood s0 utility u s → HasDerivAt (E.welfare utility u s) 0 0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) {w : CommodityClassification.Equilibrium.Vec (k + 1)},
  w ∈ CommodityClassification.CESCost.PositivePrices (k + 1) → E.costs w = Matrix.mulVec (E.currentInputs w) w

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) {w : CommodityClassification.Equilibrium.Vec (k + 1)},
  w ∈ CommodityClassification.CESCost.PositivePrices (k + 1) → ∀ (i : Fin n), E.costs w i - E.currentInputs w i ⬝ᵥ w = 0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) {abar : CommodityClassification.Equilibrium.Vec (k + 1)}
  {y : CommodityClassification.Equilibrium.PolicyPrice k} {s : ℝ},
  E.currentPrice y.2 ∈ CommodityClassification.CESCost.PositivePrices (k + 1) →
    E.excess abar (y, s) = 0 → E.costs (E.currentPrice y.2) ⬝ᵥ E.quantities y + s = E.currentPrice y.2 ⬝ᵥ abar

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) {abar : CommodityClassification.Equilibrium.Vec (k + 1)}
  {y : CommodityClassification.Equilibrium.PolicyPrice k} {s : ℝ},
  E.currentPrice y.2 ∈ CommodityClassification.CESCost.PositivePrices (k + 1) →
    E.excess abar (y, s) = 0 → E.prices y ⬝ᵥ E.quantities y + s = E.householdIncome abar y

∀ {n k : ℕ}
  {E : CommodityClassification.Equilibrium.Model n k} {utility : CommodityClassification.Equilibrium.Vec n → ℝ}
  {u : ℝ → CommodityClassification.Equilibrium.Vec k} {s : ℝ → ℝ},
  E.WelfareExpansion utility u s →
    E.lossCoefficient = 0 → (fun t => E.welfare utility u s 0 - E.welfare utility u s t) =o[nhds 0] fun t => t ^ 2

∀ {n k g : ℕ}
  (F : CommodityClassification.Equilibrium.BenchmarkFamily n k g) (C : F.Candidate),
  (F.model C).lossCoefficient = F.coefficient ↑C

∀ {n g : ℕ}
  (F0 : CommodityClassification.Equilibrium.BenchmarkFamily n 0 g) (C : CommodityClassification.Equilibrium.Mat n 0),
  F0.coefficient C = F0.b ⬝ᵥ Matrix.mulVec F0.D F0.b

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (h : E.DemandC1) (hK : Matrix.PosDef E.K) (s0 : ℝ),
  ContDiffAt ℝ 1 (fun t => E.quantities (t, E.localPricePath h hK s0 t)) 0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (h : E.DemandC1) (hK : Matrix.PosDef E.K) (s0 : ℝ),
  ∃ I, IsOpen I ∧ 0 ∈ I ∧ ∀ t ∈ I, ContDiffAt ℝ 1 (fun t => E.quantities (t, E.localPricePath h hK s0 t)) t

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (h : E.DemandC1) (hK : Matrix.PosDef E.K) (s0 : ℝ),
  ContinuousAt (deriv fun t => E.quantities (t, E.localPricePath h hK s0 t)) 0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k) (h : E.DemandC1) (hK : Matrix.PosDef E.K) (s0 : ℝ),
  ContinuousAt (fun t => E.b ⬝ᵥ deriv (fun x => E.quantities (x, E.localPricePath h hK s0 x)) t) 0

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k),
  E.lossCoefficient = E.b ⬝ᵥ Matrix.mulVec E.D E.b + E.m ⬝ᵥ E.zSolution

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k),
  Matrix.PosDef E.D → Matrix.PosDef E.K → E.adjustmentObjective E.zSolution = E.lossCoefficient

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k),
  Matrix.PosDef E.D → Matrix.PosDef E.K → IsLeast (Set.range E.adjustmentObjective) E.lossCoefficient

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k),
  Matrix.PosDef E.D → Matrix.PosDef E.K → Matrix.PosSemidef E.substitutionMatrix → 0 ≤ E.lossCoefficient

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k),
  Matrix.PosDef E.D → Matrix.PosDef E.K → E.lossCoefficient ≤ E.b ⬝ᵥ Matrix.mulVec E.D E.b

∀ {n k : ℕ}
  (E : CommodityClassification.Equilibrium.Model n k),
  Matrix.PosDef E.D → Matrix.PosDef E.K → Matrix.PosDef E.substitutionMatrix → E.b ≠ 0 → 0 < E.lossCoefficient

∀ {n k r : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n k r) (U : Set (CommodityClassification.FixedAnswer.Mat r k)),
  a.Hypotheses U → a.m₀ = 0 → ∀ (nu : ℝ), (∀ Z ∈ U, nu - a.F (a.point Z) = nu) ↔ a.r_N = 0

∀ {n k r : ℕ}
  (a : CommodityClassification.FixedAnswer.Data n k r),
  a.m₀ = 0 → a.r_N = 0 → ∀ (nu : ℝ), ∀ Z ∈ a.AdmissibleCoordinates, nu - a.F (a.point Z) = nu
